item.aggregated_output:
  1	# This file provides compatibility for NixOS to run in a container on vpsAdminOS
  2	# hosts.
  3	#
  4	# If you're experiencing issues, try updating this file to the latest version
  5	# from vpsAdminOS repository:
  6	#
  7	#   https://github.com/vpsfreecz/vpsadminos/blob/staging/os/lib/nixos-container/stable/vpsadminos.nix
  8	
  9	{
 10	  config,
 11	  lib,
 12	  options,
 13	  pkgs,
 14	  utils,
 15	  ...
 16	}:
 17	let
 18	  inherit (lib)
 19	    mkDefault
 20	    mkOverride
 21	    mkForce
 22	    ;
 23	
 24	  legacyUsers = !config.systemd.sysusers.enable && !config.services.userborn.enable;
 25	  bootSpecialFileSystemOpts = options.boot.specialFileSystems.type.getSubOptions { };
 26	  bootNeededFileSystems = lib.pipe config.fileSystems [
 27	    (lib.filterAttrs (_: v: utils.fsNeededForBoot v))
 28	    (builtins.mapAttrs (
 29	      path: v:
 30	      lib.warnIf (v.autoFormat || v.autoResize || v.encrypted.enable || v.overlay.workdir != null)
 31	        "fileSystems.${path} has options set that are not supported by boot.specialFileSystems."
 32	        (lib.intersectAttrs bootSpecialFileSystemOpts v)
 33	    ))
 34	  ];
 35	  bootNeededBindMounts = lib.filter (
 36	    mount:
 37	    (mount.enable or true)
 38	    && mount ? where
 39	    && mount ? what
 40	    && (mount.type or null) == "none"
 41	    && builtins.elem "bind" (lib.splitString "," (mount.options or ""))
 42	    && builtins.elem mount.where utils.pathsNeededForBoot
 43	  ) config.systemd.mounts;
 44	  coversPath = parent: path: parent == path || lib.hasPrefix "${lib.removeSuffix "/" parent}/" path;
 45	  earlyMounts = builtins.attrValues config.boot.specialFileSystems;
 46	  directoryBind =
 47	    mount:
 48	    lib.any (option: builtins.elem option mount.options) [
 49	      "bind"
 50	      "rbind"
 51	    ];
 52	  persistedStateMounts = lib.filter (
 53	    mount:
 54	    mount.mountPoint != "/"
 55	    && lib.any (coversPath mount.mountPoint) [
 56	      "/var/lib/nixos"
 57	      "/var/log"
 58	    ]
 59	  ) earlyMounts;
 60	  selectedStateMount =
 61	    mount: lib.any (selected: selected.mountPoint == mount.mountPoint) persistedStateMounts;
 62	  # Membership only: the upstream earlyMountScript still orders every mount.
 63	  requiredStateMounts = map (entry: entry.mount) (
 64	    lib.genericClosure {
 65	      startSet = map (mount: {
 66	        key = mount.mountPoint;
 67	        inherit mount;
 68	      }) persistedStateMounts;
 69	      operator =
 70	        entry:
 71	        map (mount: {
 72	          key = mount.mountPoint;
 73	          inherit mount;
 74	        }) (lib.filter (mount: utils.fsBefore mount entry.mount) earlyMounts);
 75	    }
 76	  );
 77	  backingMounts =
 78	    source:
 79	    lib.concatMap (mount: [
 80	      (if directoryBind mount then "bind" else "filesystem")
 81	      (toString mount.device)
 82	      mount.mountPoint
 83	    ]) (lib.filter (mount: coversPath mount.mountPoint source) earlyMounts);
 84	
 85	  persistedSpecialfs = ''
 86	    # Only missing directories receive root/0755 defaults; keep existing metadata.
 87	    vpsadminosPrepareStateDirectory() {
 88	      local path="$1" parent
 89	      if [ -e "$path" ] || [ -L "$path" ]; then
 90	        [ -d "$path" ] || return 1
 91	        return 0
 92	      fi
 93	      parent=$(dirname -- "$path") || return 1
 94	      vpsadminosPrepareStateDirectory "$parent" || return 1
 95	      mkdir -m 0755 -- "$path" || return 1
 96	    }
 97	    vpsadminosMountRequired() {
 98	      local source="$1" target="$2" options="$3" fsType="$4" selected="$5" directoryBind="$6"
 99	      local backingType backingSource backing mounted=false mountStatus
100	      shift 6
101	      # Exact declared early mountpoints must be available, including / when
102	      # configured. Undeclared host binds retain their existing host contract.
103	      while [ "$#" -gt 0 ]; do
104	        backingType="$1" backingSource="$2" backing="$3"
105	        shift 3
106	        mountpoint -q -- "$backing" || return 1
107	        if [ "$backingType" = bind ]; then
108	          [ -d "$backingSource" ] && [ -d "$backing" ] && [ "$backingSource" -ef "$backing" ] || return 1
109	        fi
110	      done
111	      if [ -e "$target" ] || [ -L "$target" ]; then
112	        [ -d "$target" ] || return 1
113	        if mountpoint -q -- "$target"; then
114	          mounted=true
115	          if "$directoryBind" && ! { [ -d "$source" ] && [ "$source" -ef "$target" ]; }; then
116	            printf 'vpsAdminOS: state destination has a different mounted source: %s\n' "$target" >&2
117	            return 1
118	          fi
119	        else
120	          mountStatus=$?
121	          # util-linux returns 32 for a directory that is not a mountpoint.
122	          [ "$mountStatus" -eq 32 ] || return 1
123	        fi
124	      fi
125	      if "$directoryBind"; then
126	        if "$selected"; then
127	          vpsadminosPrepareStateDirectory "$source" || return 1
128	        else
129	          # A prerequisite bind must not hide unavailable storage with mkdir.
130	          [ -d "$source" ] || return 1
131	        fi
132	      fi
133	      if "$mounted"; then
134	        mount -t "$fsType" -o "remount,$options" "$source" "$target" || return 1
135	      else
136	        vpsadminosPrepareStateDirectory "$target" || return 1
137	        mount -t "$fsType" -o "$options" "$source" "$target" || return 1
138	      fi
139	      mountpoint -q -- "$target" || return 1
140	      if "$directoryBind"; then
141	        [ -d "$source" ] && [ "$source" -ef "$target" ] || return 1
142	      fi
143	    }
144	    specialMount() {
145	      local device="$1" mountPoint="$2" options="$3" fsType="$4"
146	      ${lib.concatMapStringsSep "\n" (mount: ''
147	        if [ "$device" = ${lib.escapeShellArg (toString mount.device)} ] && [ "$mountPoint" = ${lib.escapeShellArg mount.mountPoint} ] && [ "$options" = ${lib.escapeShellArg (lib.concatStringsSep "," mount.options)} ] && [ "$fsType" = ${lib.escapeShellArg mount.fsType} ]; then
148	          # Exit the parent activation shell: its ERR trap alone permits users.
149	          if ! vpsadminosMountRequired "$device" "$mountPoint" "$options" "$fsType" ${
150	            if selectedStateMount mount then "true" else "false"
151	          } ${if directoryBind mount then "true" else "false"} ${
152	            lib.escapeShellArgs (
153	              if directoryBind mount && selectedStateMount mount then
154	                backingMounts (toString mount.device)
155	              else
156	                [ ]
157	            )
158	          }; then
159	            printf 'vpsAdminOS: persisted state unavailable; refusing user allocation\n' >&2
160	            exit 1
161	          fi
162	          return 0
163	        fi
164	      '') requiredStateMounts}
165	      # Keep this fallback aligned with upstream activation-script.nix specialfs.
166	      # The global earlyMountScript remains responsible for all mount ordering.
167	      if mountpoint -q "$mountPoint"; then
168	        local options="remount,$options"
169	      else
170	        mkdir -p "$mountPoint"
171	        chmod 0755 "$mountPoint"
172	      fi
173	      mount -t "$fsType" -o "$options" "$device" "$mountPoint"
174	    }
175	    source ${config.system.build.earlyMountScript}
176	  '';
177	
178	  nameservers = [
179	    "1.1.1.1"
180	    "2606:4700:4700::1111"
181	  ];
182	in
183	{
184	  networking.nameservers = mkDefault nameservers;
185	  services.resolved.settings.Resolve = mkDefault { FallbackDNS = nameservers; };
186	  networking.dhcpcd.extraConfig = "noipv4ll";
187	
188	  systemd.services.systemd-oomd.enable = false;
189	  systemd.sockets."systemd-journald-audit".enable = false;
190	  systemd.mounts = [
191	    {
192	      where = "/sys/kernel/debug";
193	      enable = false;
194	    }
195	  ];
196	  systemd.services.rpc-gssd.enable = false;
197	
198	  # Needed for systemd since v258, see issue #39036
199	  systemd.services.console-getty.serviceConfig = {
200	    StandardInput = "null";
201	    StandardOutput = "null";
202	  };
203	
204	  # Due to our restrictions in /sys, the default systemd-udev-trigger fails
205	  # on accessing PCI devices, etc. Override it to match only network devices.
206	  # In addition, boot.isContainer prevents systemd-udev-trigger.service from
207	  # being enabled at all, so add it explicitly.
208	  systemd.additionalUpstreamSystemUnits = [
209	    "systemd-udev-trigger.service"
210	  ];
211	  systemd.services.systemd-udev-trigger.serviceConfig.ExecStart = [
212	    ""
213	    "-udevadm trigger --subsystem-match=net --action=add"
214	  ];
215	
216	  boot.isContainer = true;
217	  boot.enableContainers = mkDefault true;
218	  boot.loader.initScript.enable = true;
219	  boot.systemdExecutable = mkDefault "/run/current-system/systemd/lib/systemd/systemd systemd.unified_cgroup_hierarchy=0";
220	  console.enable = true;
221	
222	  # Containers have no initrd. Keep the complete promotion and global mount
223	  # order, including state binds: LXC's proc mount can skip stage 2's mounts.
224	  boot.specialFileSystems =
225	    let
226	      bootNeededBinds = builtins.listToAttrs (
227	        map (mount: {
228	          name = mount.where;
229	          value = lib.intersectAttrs bootSpecialFileSystemOpts {
230	            device = mount.what;
231	            fsType = mount.type or "none";
232	            options = lib.splitString "," (mount.options or "");
233	          };
234	        }) bootNeededBindMounts
235	      );
236	    in
237	    bootNeededFileSystems
238	    // bootNeededBinds
239	    // {
240	      "/run/keys".fsType = mkForce "tmpfs";
241	    };
242	
243	  system.activationScripts = lib.mkIf (legacyUsers && persistedStateMounts != [ ]) {
244	    specialfs = mkOverride 90 {
245	      text = persistedSpecialfs;
246	      supportsDryActivation = false;
247	    };
248	    users.deps = [ "specialfs" ];
249	  };
250	
251	  # Overrides for <nixpkgs/nixos/modules/virtualisation/container-config.nix>
252	  documentation.enable = mkOverride 500 true;
253	  documentation.nixos.enable = mkOverride 500 true;
254	  networking.useHostResolvConf = mkOverride 500 false;
255	  services.openssh.startWhenNeeded = mkOverride 500 false;
256	
257	  # Bring up the network, /ifcfg.{add,del} are supplied by the vpsAdminOS host
258	  systemd.services.networking-setup = {
259	    description = "Load network configuration provided by the vpsAdminOS host";
260	    before = [ "network.target" ];
261	    wantedBy = [ "network.target" ];
262	    after = [ "network-pre.target" ];
263	    path = [ pkgs.iproute2 ];
264	    serviceConfig = {
265	      Type = "oneshot";
266	      RemainAfterExit = true;
267	      ExecStart = "${pkgs.bash}/bin/bash /ifcfg.add";
268	      ExecStop = "${pkgs.bash}/bin/bash /ifcfg.del";
269	    };
270	    unitConfig.ConditionPathExists = "/ifcfg.add";
271	    restartIfChanged = false;
272	  };
273	}

